// A. Stack Allocation and Initialization
#define MAX_ITEMS 5
int page_table[MAX_ITEMS];      // Fixed size allocated on stack
char name[] = "Reference";      // Size inferred (10 chars including '\0')

// Partial initialization (remaining elements zeroed out)
float initial_data[4] = {1.0, 2.5};

page_table[0] = 42;
page_table[MAX_ITEMS - 1] = 99;


// B. Size Calculation and Memory
int data[10];

// Total memory occupied by the array (in bytes)
size_t total_size = sizeof(data);

// Size of one element
size_t element_size = sizeof(data[0]);

// Length (only works locally before array decay)
size_t length = total_size / element_size; // Length = 10

// Warning: Pointer size (8 bytes typically), NOT array size
int* ptr = data;
size_t bad_size = sizeof(ptr);


// C. Array Decay (Passing to Functions)
// Arrays decay to pointers when passed. Size must be passed separately.
void print_page(int* array_ptr, size_t count) {
    if (count > 0) {
        // Accessing using pointer arithmetic or index
        int last_val = array_ptr[count - 1];
    }
}

// Function declaration using array syntax (identical decay)
void process(int a[]) {}

int counts[20];
print_page(counts, 20);
process(counts);
